STR_AR[mw2_exec_mismatch]="[!] تحذير: الملف تنفيذي (ELF/PE) لكن امتداده يوحي بأنه مستند/صورة/وسائط — مؤشر خطر قوي!"
STR_EN[mw2_exec_mismatch]="[!] Warning: The file is executable (ELF/PE) but its extension suggests a document/image/media file — strong danger indicator!"
STR_FR[mw2_exec_mismatch]="[!] Avertissement : le fichier est exécutable (ELF/PE) mais son extension suggère un document/image/média — indicateur de danger fort !"
STR_ES[mw2_exec_mismatch]="[!] Advertencia: el archivo es ejecutable (ELF/PE) pero su extensión sugiere un documento/imagen/medio — ¡fuerte indicador de peligro!"
STR_DE[mw2_exec_mismatch]="[!] Warnung: Die Datei ist ausführbar (ELF/PE), aber ihre Erweiterung deutet auf ein Dokument/Bild/Medium hin — starker Gefahrenindikator!"
STR_TR[mw2_exec_mismatch]="[!] Uyarı: Dosya çalıştırılabilir (ELF/PE) ancak uzantısı bir belge/resim/medya olduğunu düşündürüyor — güçlü tehlike göstergesi!"
STR_FA[mw2_exec_mismatch]="[!] هشدار: فایل اجرایی است (ELF/PE) اما پسوند آن نشان‌دهنده سند/تصویر/رسانه است — نشانه خطر قوی!"
STR_RU[mw2_exec_mismatch]="[!] Внимание: файл является исполняемым (ELF/PE), но его расширение указывает на документ/изображение/медиа — серьёзный признак опасности!"
STR_KU[mw2_exec_mismatch]="[!] ئاگاداری: فایلەکە جێبەجێکراوە (ELF/PE) بەڵام پاشگرەکەی ئاماژە بە بەڵگەنامە/وێنە/میدیا دەکات — نیشانەی مەترسی بەهێز!"
STR_ZH[mw2_exec_mismatch]="[!] 警告：该文件是可执行文件（ELF/PE），但其扩展名暗示为文档/图片/媒体 — 强烈的危险信号！"

STR_AR[mw2_exec_ok]="[i] الملف تنفيذي (ELF/PE). تأكد أنك تعرف مصدره قبل تشغيله."
STR_EN[mw2_exec_ok]="[i] The file is executable (ELF/PE). Make sure you know its source before running it."
