STR_AR[mw4_high_entropy]="[!] تحذير: إنتروبيا عالية جداً — الملف على الأغلب مشفّر أو محزوم (packed) — مؤشر شائع بالبرمجيات الخبيثة."
STR_EN[mw4_high_entropy]="[!] Warning: Very high entropy — the file is likely encrypted or packed — a common malware indicator."
STR_FR[mw4_high_entropy]="[!] Avertissement : entropie très élevée — le fichier est probablement chiffré ou compressé — indicateur courant de logiciel malveillant."
STR_ES[mw4_high_entropy]="[!] Advertencia: entropía muy alta — el archivo probablemente está cifrado o empaquetado — indicador común de malware."
STR_DE[mw4_high_entropy]="[!] Warnung: Sehr hohe Entropie — die Datei ist wahrscheinlich verschlüsselt oder gepackt — häufiger Malware-Indikator."
STR_TR[mw4_high_entropy]="[!] Uyarı: Çok yüksek entropi — dosya muhtemelen şifreli veya paketlenmiş — yaygın bir kötü amaçlı yazılım göstergesi."
STR_FA[mw4_high_entropy]="[!] هشدار: آنتروپی بسیار بالا — فایل احتمالاً رمزنگاری‌شده یا بسته‌بندی‌شده است — نشانه رایج بدافزار."
STR_RU[mw4_high_entropy]="[!] Внимание: очень высокая энтропия — файл, вероятно, зашифрован или упакован — распространённый признак вредоносного ПО."
STR_KU[mw4_high_entropy]="[!] ئاگاداری: ئێنترۆپی زۆر بەرزە — فایلەکە زۆرجار نهێنیکراو یان پاکەتکراوە — نیشانەیەکی باوی مالوێر."
STR_ZH[mw4_high_entropy]="[!] 警告：熵值非常高 — 文件很可能已加密或加壳 — 常见的恶意软件指标。"

STR_AR[mw4_medium_entropy]="[i] إنتروبيا متوسطة-عالية — قد يكون الملف مضغوط أو ثنائي عادي."
STR_EN[mw4_medium_entropy]="[i] Medium-high entropy — the file may be compressed or a normal binary."
