STR_AR[har5_default_accept]="[!] السياسة الافتراضية لسلسلة INPUT هي ACCEPT — يُفضّل تكون DROP مع قواعد سماح محددة."
STR_EN[har5_default_accept]="[!] The default policy for the INPUT chain is ACCEPT — it should preferably be DROP with specific allow rules."
STR_FR[har5_default_accept]="[!] La politique par défaut de la chaîne INPUT est ACCEPT — elle devrait être DROP avec des règles d'autorisation spécifiques."
STR_ES[har5_default_accept]="[!] La política predeterminada de la cadena INPUT es ACCEPT — debería ser DROP con reglas de permiso específicas."
STR_DE[har5_default_accept]="[!] Die Standardrichtlinie für die INPUT-Kette ist ACCEPT — sie sollte vorzugsweise DROP mit spezifischen Erlaubnisregeln sein."
STR_TR[har5_default_accept]="[!] INPUT zincirinin varsayılan politikası ACCEPT — tercihen belirli izin kurallarıyla DROP olmalıdır."
STR_FA[har5_default_accept]="[!] سیاست پیش‌فرض زنجیره INPUT برابر ACCEPT است — بهتر است DROP با قوانین مجاز مشخص باشد."
STR_RU[har5_default_accept]="[!] Политика по умолчанию для цепочки INPUT — ACCEPT — предпочтительнее DROP с явными разрешающими правилами."
STR_KU[har5_default_accept]="[!] سیاسەتی بنەڕەتی زنجیرەی INPUT بریتییە لە ACCEPT — باشترە DROP بێت لەگەڵ یاسای ڕێگەپێدانی دیاریکراو."
STR_ZH[har5_default_accept]="[!] INPUT 链的默认策略为 ACCEPT — 建议改为 DROP 并配合明确的允许规则。"

