# ===== أداة 12: تقييم استدلالي لملف غير معروف =====
STR_AR[mw12_title]="🧪 تقييم استدلالي لملف غير معروف"
STR_EN[mw12_title]="🧪 Unknown File Triage"
STR_AR[mw12_disclaimer]="تقييم بنقاط موزونة مفسَّرة (entropy + أنماط شيفرة + خصائص نظام + تطابق قاعدة استخبارات) — مو نموذج تعلّم آلي، كل نقطة بالنتيجة لها سبب واضح تقدر تراجعه."
STR_EN[mw12_disclaimer]="An explainable weighted-signal score (entropy + code patterns + filesystem traits + intel-DB match) — not a trained ML model; every point in the score has a clear, reviewable reason."
STR_AR[mw12_score_label]="النتيجة"
STR_EN[mw12_score_label]="Score"
STR_AR[mw12_reasons_title]="الأسباب:"
STR_EN[mw12_reasons_title]="Reasons:"
STR_AR[mw12_no_signals]="ما فيه إشارات مشبوهة رُصدت."
STR_EN[mw12_no_signals]="No suspicious signals detected."
STR_AR[mw12_footer_note]="هذا تقييم استدلالي مساعد للفرز الأولي، مو حكم قطعي — راجع الملف يدوياً قبل أي إجراء حاسم (حذف/حجر صحي)."
STR_EN[mw12_footer_note]="This is an assistive triage score, not a definitive verdict — review the file manually before any destructive action (delete/quarantine)."
