STR_AR[limitations_title]="⚠️  حدود معروفة بالأداة (Known Limitations)"
STR_EN[limitations_title]="⚠️  Known Tool Limitations"
STR_FR[limitations_title]="⚠️  Limites connues de l'outil"
STR_ES[limitations_title]="⚠️  Limitaciones conocidas de la herramienta"
STR_DE[limitations_title]="⚠️  Bekannte Einschränkungen des Tools"
STR_TR[limitations_title]="⚠️  Aracın Bilinen Sınırlamaları"
STR_FA[limitations_title]="⚠️  محدودیت‌های شناخته‌شده ابزار"
STR_RU[limitations_title]="⚠️  Известные ограничения инструмента"
STR_KU[limitations_title]="⚠️  سنووردارییە ناسراوەکانی ئامرازەکە"
STR_ZH[limitations_title]="⚠️  工具的已知局限性"

STR_AR[limitations_item1]="لا يوجد كشف سلوكي حي (Behavior-based) فعلي بعد — كل الأداة حالياً static analysis فقط (فحص محتوى/hash/entropy/YARA-lite). مراقبة العملية وقت التشغيل الفعلي (اتصالات شبكية لحظية، سلوك مشبوه أثناء التنفيذ) غير مبنية بعد."
STR_EN[limitations_item1]="No real behavior-based detection yet — the entire tool is currently static analysis only (content/hash/entropy/YARA-lite checks). Live runtime process monitoring (real-time network connections, suspicious behavior during execution) is not built yet."
STR_FR[limitations_item1]="Aucune détection comportementale réelle pour l'instant — l'outil entier repose uniquement sur l'analyse statique (contenu/hash/entropie/YARA-lite). La surveillance des processus en temps réel (connexions réseau en direct, comportement suspect pendant l'exécution) n'est pas encore implémentée."
STR_ES[limitations_item1]="Aún no hay detección real basada en comportamiento — toda la herramienta es actualmente solo análisis estático (contenido/hash/entropía/YARA-lite). La monitorización de procesos en tiempo real (conexiones de red en vivo, comportamiento sospechoso durante la ejecución) todavía no está implementada."
STR_DE[limitations_item1]="Noch keine echte verhaltensbasierte Erkennung — das gesamte Tool basiert derzeit nur auf statischer Analyse (Inhalt/Hash/Entropie/YARA-lite). Eine Echtzeit-Prozessüberwachung (live Netzwerkverbindungen, verdächtiges Verhalten während der Ausführung) ist noch nicht implementiert."
STR_TR[limitations_item1]="Henüz gerçek davranış tabanlı algılama yok — araç şu anda tamamen statik analize dayanıyor (içerik/hash/entropi/YARA-lite kontrolleri). Gerçek zamanlı süreç izleme (canlı ağ bağlantıları, çalışma sırasında şüpheli davranış) henüz oluşturulmadı."
STR_FA[limitations_item1]="هنوز تشخیص واقعی مبتنی بر رفتار وجود ندارد — کل ابزار در حال حاضر فقط تحلیل ایستا (بررسی محتوا/هش/آنتروپی/YARA-lite) است. نظارت لحظه‌ای بر فرآیندها (اتصالات شبکه‌ی زنده، رفتار مشکوک حین اجرا) هنوز ساخته نشده است."
STR_RU[limitations_item1]="Пока нет реального поведенческого обнаружения — весь инструмент сейчас основан только на статическом анализе (проверка содержимого/хэша/энтропии/YARA-lite). Мониторинг процессов в реальном времени (живые сетевые соединения, подозрительное поведение во время выполнения) ещё не реализован."
STR_KU[limitations_item1]="هێشتا هیچ دۆزینەوەیەکی ڕاستەقینەی لەسەر بنەمای ڕەفتار نییە — ئامرازەکە بە تەواوی تەنها شیکاری وەستاوە (پشکنینی ناوەڕۆک/hash/entropy/YARA-lite). چاودێری کاتی-ڕاستەقینەی پرۆسەکان (پەیوەندی تۆڕی زیندوو، ڕەفتاری گومانلێکراو لە کاتی جێبەجێکردندا) هێشتا دروست نەکراوە."
STR_ZH[limitations_item1]="目前还没有真正的基于行为的检测——整个工具目前仅进行静态分析(内容/哈希/熵/YARA-lite 检测)。实时进程监控(实时网络连接、执行期间的可疑行为)尚未构建。"

STR_AR[limitations_item2]="مصادر القواعد الحيّة (rules_updater.sh + sources.txt) غير مُتحقق منها بمصدر حقيقي — الآلية (تحقق من الصيغة، نسخ احتياطي، دمج) جاهزة ومختبرة بمصادر تجريبية، لكنها معطّلة افتراضياً (enabled=0) لأنه ما تم التحقق من أي رابط مصدر حي فعلي."
STR_EN[limitations_item2]="Live rule sources (rules_updater.sh + sources.txt) are unverified against a real source — the mechanism (format validation, backup, merge) is built and tested with mock sources, but disabled by default (enabled=0) because no real live source URL has been verified."
STR_FR[limitations_item2]="Les sources de règles en direct (rules_updater.sh + sources.txt) n'ont pas été vérifiées avec une source réelle — le mécanisme (validation du format, sauvegarde, fusion) est construit et testé avec des sources fictives, mais désactivé par défaut (enabled=0) car aucune URL de source réelle n'a été vérifiée."
STR_ES[limitations_item2]="Las fuentes de reglas en vivo (rules_updater.sh + sources.txt) no se han verificado contra una fuente real — el mecanismo (validación de formato, copia de seguridad, fusión) está construido y probado con fuentes de prueba, pero deshabilitado por defecto (enabled=0) porque no se ha verificado ninguna URL de fuente real."
STR_DE[limitations_item2]="Live-Regelquellen (rules_updater.sh + sources.txt) sind nicht anhand einer echten Quelle verifiziert — der Mechanismus (Formatprüfung, Backup, Zusammenführung) ist gebaut und mit Testquellen geprüft, aber standardmäßig deaktiviert (enabled=0), da keine echte Live-Quell-URL verifiziert wurde."
STR_TR[limitations_item2]="Canlı kural kaynakları (rules_updater.sh + sources.txt) gerçek bir kaynağa karşı doğrulanmadı — mekanizma (biçim doğrulama, yedekleme, birleştirme) oluşturuldu ve sahte kaynaklarla test edildi, ancak gerçek bir canlı kaynak URL'si doğrulanmadığı için varsayılan olarak devre dışı (enabled=0)."
STR_FA[limitations_item2]="منابع قوانین زنده (rules_updater.sh + sources.txt) در برابر یک منبع واقعی تأیید نشده‌اند — مکانیزم (اعتبارسنجی فرمت، پشتیبان‌گیری، ادغام) ساخته و با منابع آزمایشی تست شده، اما به‌طور پیش‌فرض غیرفعال است (enabled=0) چون هیچ URL منبع زنده‌ی واقعی تأیید نشده است."
STR_RU[limitations_item2]="Источники живых правил (rules_updater.sh + sources.txt) не проверены на реальном источнике — механизм (проверка формата, резервное копирование, слияние) построен и протестирован на тестовых источниках, но по умолчанию отключён (enabled=0), так как ни один реальный URL источника не был проверен."
STR_KU[limitations_item2]="سەرچاوە زیندووەکانی یاسا (rules_updater.sh + sources.txt) بەرامبەر بە سەرچاوەیەکی ڕاستەقینە پشتڕاست نەکراونەتەوە — میکانیزمەکە (پشتڕاستکردنەوەی فۆرمات، پاڵپشتیگرتن، تێکەڵکردن) دروستکراوە و لەگەڵ سەرچاوەی ئەزموونی تاقیکراوەتەوە، بەڵام بە بنەڕەت ناچالاکە (enabled=0) چونکە هیچ بەستەرێکی سەرچاوەی زیندووی ڕاستەقینە پشتڕاست نەکراوەتەوە."
STR_ZH[limitations_item2]="实时规则源(rules_updater.sh + sources.txt)尚未针对真实来源进行验证——该机制(格式验证、备份、合并)已构建并使用模拟来源测试,但默认处于禁用状态(enabled=0),因为尚未验证任何真实的实时来源 URL。"

STR_AR[limitations_item3]="raqib.sh نفسه ما جُرّب طرف-لطرف على جهاز حقيقي — كل الاختبارات الحالية عبر محاكاة (stub functions) داخل بيئة التطوير، مو تشغيل فعلي كامل للسكربت."
STR_EN[limitations_item3]="raqib.sh itself has not been end-to-end tested on a real machine — all current tests use stub functions inside the dev environment, not a full real run of the script."
STR_FR[limitations_item3]="raqib.sh lui-même n'a pas été testé de bout en bout sur une vraie machine — tous les tests actuels utilisent des fonctions factices (stubs) dans l'environnement de développement, pas une exécution réelle complète du script."
STR_ES[limitations_item3]="raqib.sh en sí no se ha probado de extremo a extremo en una máquina real — todas las pruebas actuales usan funciones simuladas (stubs) dentro del entorno de desarrollo, no una ejecución real completa del script."
STR_DE[limitations_item3]="raqib.sh selbst wurde noch nicht End-to-End auf einer echten Maschine getestet — alle aktuellen Tests verwenden Stub-Funktionen innerhalb der Entwicklungsumgebung, keinen vollständigen echten Lauf des Skripts."
STR_TR[limitations_item3]="raqib.sh'nin kendisi gerçek bir makinede uçtan uca test edilmedi — mevcut tüm testler geliştirme ortamı içindeki sahte (stub) fonksiyonları kullanır, betiğin gerçek ve tam bir çalıştırması değil."
STR_FA[limitations_item3]="خود raqib.sh به‌صورت سرتاسری روی یک دستگاه واقعی آزمایش نشده است — همه‌ی تست‌های فعلی از توابع جایگزین (stub) درون محیط توسعه استفاده می‌کنند، نه یک اجرای واقعی و کامل اسکریپت."
STR_RU[limitations_item3]="Сам raqib.sh не был протестирован сквозным образом на реальной машине — все текущие тесты используют заглушки (stub-функции) внутри среды разработки, а не полный реальный запуск скрипта."
STR_KU[limitations_item3]="خودی raqib.sh بە شێوەی سەرتاسەری لەسەر ماشێنێکی ڕاستەقینە تاقی نەکراوەتەوە — هەموو تاقیکردنەوە ئێستاکان فەنکشنی stub بەکاردەهێنن لەناو ژینگەی گەشەپێدان، نەک جێبەجێکردنێکی ڕاستەقینەی تەواوی سکریپتەکە."
STR_ZH[limitations_item3]="raqib.sh 本身尚未在真实设备上进行端到端测试——目前的所有测试都在开发环境中使用桩函数(stub functions),而不是脚本的完整真实运行。"

STR_AR[limitations_item4]="حالة static_dropper بكورپس الاختبار معروفة ومتروكة عمداً — ثنائي ساكن بدون نص أو سلوك ظاهر بالتحليل الساكن، وبالتالي لا ينكشف حالياً؛ هذا حد متوقع لأي أداة static-only ويحتاج طبقة سلوكية حية لسده."
STR_EN[limitations_item4]="The static_dropper case in the test corpus is a known, deliberately-left gap — a static binary with no visible strings/behavior under static analysis, so it currently goes undetected; this is an expected limit of any static-only tool and needs a live behavioral layer to close."
STR_FR[limitations_item4]="Le cas static_dropper dans le corpus de test est une lacune connue et volontairement laissée — un binaire statique sans chaînes/comportement visible en analyse statique, donc actuellement non détecté ; c'est une limite attendue de tout outil purement statique et nécessite une couche comportementale en direct pour la combler."
STR_ES[limitations_item4]="El caso static_dropper en el corpus de pruebas es una brecha conocida y dejada deliberadamente — un binario estático sin cadenas/comportamiento visible en el análisis estático, por lo que actualmente no se detecta; esta es una limitación esperada de cualquier herramienta solo estática y necesita una capa de comportamiento en vivo para cerrarla."
STR_DE[limitations_item4]="Der static_dropper-Fall im Testkorpus ist eine bekannte, absichtlich belassene Lücke — eine statische Binärdatei ohne sichtbare Strings/Verhalten bei statischer Analyse, wird also derzeit nicht erkannt; das ist eine erwartete Grenze jedes rein statischen Tools und erfordert eine Live-Verhaltensschicht, um sie zu schließen."
STR_TR[limitations_item4]="Test derlemindeki static_dropper vakası bilinen ve kasıtlı olarak bırakılan bir boşluktur — statik analizde görünür dize/davranışı olmayan statik bir ikili dosya, bu yüzden şu anda tespit edilmiyor; bu, yalnızca statik herhangi bir aracın beklenen bir sınırıdır ve kapatmak için canlı bir davranışsal katmana ihtiyaç duyar."
STR_FA[limitations_item4]="مورد static_dropper در پیکره‌ی آزمایشی، شکافی شناخته‌شده و عمداً باقی‌مانده است — یک باینری ایستا بدون رشته‌ها/رفتار قابل مشاهده در تحلیل ایستا، بنابراین در حال حاضر شناسایی نمی‌شود؛ این محدودیت مورد انتظار هر ابزار صرفاً ایستا است و برای رفعش به یک لایه‌ی رفتاری زنده نیاز دارد."
STR_RU[limitations_item4]="Случай static_dropper в тестовом корпусе — известный, намеренно оставленный пробел — статический бинарный файл без видимых строк/поведения при статическом анализе, поэтому сейчас не обнаруживается; это ожидаемое ограничение любого чисто статического инструмента, требующее живого поведенческого слоя для устранения."
STR_KU[limitations_item4]="حاڵەتی static_dropper لە کۆرپەسی تاقیکردنەوەدا کەلێنێکی ناسراو و بەئارادانراوە — دووانەیەکی وەستاو بەبێ ڕشتە/ڕەفتاری دیارە لە شیکاری وەستاودا، بۆیە ئێستا ناناسرێتەوە؛ ئەمە سنوورێکی چاوەڕوانکراوە بۆ هەر ئامرازێکی تەنها-وەستاو و پێویستی بە چینێکی ڕەفتاری زیندوو هەیە بۆ داخستنی."
STR_ZH[limitations_item4]="测试语料库中的 static_dropper 案例是一个已知且故意保留的漏检——一个在静态分析下没有可见字符串/行为的静态二进制文件,因此目前无法被检测到;这是任何纯静态工具的预期局限,需要实时行为层才能弥补。"

STR_AR[limitations_item5]="صفر قواعد .yar حقيقية بالمشروع حالياً — الدعم التقني لتحميل واستخدام ملفات .yar من ثنائي yara الحقيقي موجود وجاهز، لكن ما فيه قواعد فعلية إلا لو مصدر خارجي يجيب وحدة."
STR_EN[limitations_item5]="Zero real .yar rules ship with the project right now — technical support for loading and using .yar files with a real yara binary exists and is ready, but there are no actual rule files unless an external source provides one."
STR_FR[limitations_item5]="Zéro règle .yar réelle n'est fournie avec le projet pour l'instant — le support technique pour charger et utiliser des fichiers .yar avec un vrai binaire yara existe et est prêt, mais il n'y a aucun fichier de règles réel à moins qu'une source externe n'en fournisse un."
STR_ES[limitations_item5]="Cero reglas .yar reales se incluyen con el proyecto actualmente — el soporte técnico para cargar y usar archivos .yar con un binario yara real existe y está listo, pero no hay archivos de reglas reales a menos que una fuente externa proporcione uno."
STR_DE[limitations_item5]="Derzeit werden null echte .yar-Regeln mit dem Projekt ausgeliefert — die technische Unterstützung zum Laden und Verwenden von .yar-Dateien mit einer echten yara-Binärdatei existiert und ist bereit, aber es gibt keine tatsächlichen Regeldateien, es sei denn, eine externe Quelle stellt eine bereit."
STR_TR[limitations_item5]="Şu anda projeyle birlikte sıfır gerçek .yar kuralı geliyor — gerçek bir yara ikili dosyasıyla .yar dosyalarını yükleme ve kullanma teknik desteği mevcut ve hazır, ancak harici bir kaynak sağlamadıkça gerçek bir kural dosyası yok."
STR_FA[limitations_item5]="در حال حاضر صفر قانون واقعی .yar همراه با پروژه ارائه می‌شود — پشتیبانی فنی برای بارگذاری و استفاده از فایل‌های .yar با یک باینری واقعی yara وجود دارد و آماده است، اما هیچ فایل قانون واقعی‌ای وجود ندارد مگر اینکه یک منبع خارجی آن را فراهم کند."
STR_RU[limitations_item5]="Сейчас в проекте нет ни одного реального .yar-правила — техническая поддержка загрузки и использования файлов .yar с реальным бинарным файлом yara существует и готова, но реальных файлов правил нет, если только внешний источник их не предоставит."
STR_KU[limitations_item5]="ئێستا سفر یاسای .yar ڕاستەقینە لەگەڵ پڕۆژەکەدا نایە — پشتگیری تەکنیکی بۆ بارکردن و بەکارهێنانی فایلی .yar لەگەڵ دووانەیەکی ڕاستەقینەی yara بوونی هەیە و ئامادەیە، بەڵام هیچ فایلی یاسای ڕاستەقینە نییە مەگەر سەرچاوەیەکی دەرەکی یەکێکی دابین بکات."
STR_ZH[limitations_item5]="目前项目中没有任何真实的 .yar 规则——使用真实的 yara 二进制文件加载和使用 .yar 文件的技术支持已经存在并已就绪,但除非有外部来源提供,否则没有实际的规则文件。"

STR_AR[limitations_item6]="لم يُختبر على أنظمة تشغيل غير بيئة التطوير الحالية — لا اختبار على macOS ولا على توزيعات Linux مختلفة بعد."
STR_EN[limitations_item6]="Not tested on any OS besides the current development environment — no testing on macOS or on other Linux distributions yet."
STR_FR[limitations_item6]="Non testé sur un autre système d'exploitation que l'environnement de développement actuel — aucun test sur macOS ni sur d'autres distributions Linux pour l'instant."
STR_ES[limitations_item6]="No probado en ningún sistema operativo aparte del entorno de desarrollo actual — todavía no hay pruebas en macOS ni en otras distribuciones Linux."
STR_DE[limitations_item6]="Nicht auf einem anderen Betriebssystem als der aktuellen Entwicklungsumgebung getestet — noch keine Tests auf macOS oder anderen Linux-Distributionen."
STR_TR[limitations_item6]="Mevcut geliştirme ortamı dışında herhangi bir işletim sisteminde test edilmedi — henüz macOS'ta veya diğer Linux dağıtımlarında test yapılmadı."
STR_FA[limitations_item6]="روی هیچ سیستم‌عاملی به‌جز محیط توسعه‌ی فعلی آزمایش نشده است — هنوز آزمایشی روی macOS یا سایر توزیع‌های لینوکس انجام نشده است."
STR_RU[limitations_item6]="Не тестировалось ни на одной ОС, кроме текущей среды разработки — пока нет тестирования на macOS или других дистрибутивах Linux."
STR_KU[limitations_item6]="لەسەر هیچ سیستەمی کارپێکردنێک جگە لە ژینگەی گەشەپێدانی ئێستا تاقی نەکراوەتەوە — هێشتا هیچ تاقیکردنەوەیەک لەسەر macOS یان دابەشکراوەکانی تری Linux نییە."
STR_ZH[limitations_item6]="除当前开发环境外,尚未在任何其他操作系统上进行测试——目前还没有在 macOS 或其他 Linux 发行版上进行测试。"

