STR_EN[upd_disabled]="Update checking is not enabled. Edit update_source.txt at the project root, point it at a URL you control (e.g. your own repo), and enable it (enabled=1) first."
STR_FR[upd_disabled]="La vérification des mises à jour n'est pas activée. Modifiez update_source.txt à la racine du projet, pointez-le vers une URL que vous contrôlez (par ex. votre propre dépôt), puis activez-le (enabled=1) d'abord."
