# Load saved language preference (defaults to Arabic)
load_lang() {
    if [ -f "$RAQIB_LANG_FILE" ]; then
        LANG_CODE="$(cat "$RAQIB_LANG_FILE" 2>/dev/null | tr -d '[:space:]')"
    fi
    case " ${LANG_CODES[*]} " in
        *" $LANG_CODE "*) : ;;
        *) LANG_CODE="ar" ;;
    esac
}
export -f load_lang

save_lang() {
    echo "$LANG_CODE" > "$RAQIB_LANG_FILE"
}
export -f save_lang

# t <key> -> prints the translated string for the current LANG_CODE,
# falling back to Arabic if the key/language is missing.
t() {
    local key="$1"
    local lc_upper
    lc_upper="$(echo "$LANG_CODE" | tr '[:lower:]' '[:upper:]')"
    local -n arr="STR_${lc_upper}" 2>/dev/null
    local val="${arr[$key]}"
    if [ -z "$val" ]; then
        local -n fb="STR_AR"
        val="${fb[$key]}"
    fi
    printf '%s' "$val"
}
export -f t

# tf <key> <arg1> <arg2> ... -> like t(), but treats the translated string
# as a printf format (with %s placeholders) and substitutes the given args.
tf() {
    local key="$1"; shift
    local fmt
    fmt="$(t "$key")"
    printf -- "$fmt" "$@"
}
export -f tf

menu_language() {
    while true; do
        show_banner
        echo -e "${BOLD}$(t lang_menu_title)${NC}"
        echo ""
        local i=1
        local code
        for code in "${LANG_CODES[@]}"; do
            local lc_upper
            lc_upper="$(echo "$code" | tr '[:lower:]' '[:upper:]')"
            local -n arr="STR_${lc_upper}"
            local marker=""
            if [ "$code" = "$LANG_CODE" ]; then marker=" ${GREEN}✓${NC}"; fi
            echo -e "  ${CYAN}${i})${NC} ${arr[lang_name]}${marker}"
            ((i++))
        done
        echo -e "  ${RED}0)${NC} $(t back)"
        echo ""
        read -rp "  $(t choice_label)" c
        if [ "$c" = "0" ]; then
            return
        elif [[ "$c" =~ ^[0-9]+$ ]] && [ "$c" -ge 1 ] && [ "$c" -le "${#LANG_CODES[@]}" ]; then
            LANG_CODE="${LANG_CODES[$((c-1))]}"
            save_lang
            echo -e "${GREEN}$(t lang_changed)${NC}"
            if [ "$LANG_CODE" != "ar" ] && [ "$LANG_CODE" != "en" ]; then
                local completeness
                completeness="$(raqib_lang_completeness "$LANG_CODE")"
                local have="${completeness%/*}"
                local total="${completeness#*/}"
                if [ "$have" -lt "$total" ]; then
                    raqib_auto_translate_missing "$LANG_CODE"
                fi
            fi
            sleep 1
            return
        else
            echo -e "${RED}$(t invalid_choice)${NC}"
            sleep 1
        fi
    done
}
export -f menu_language

