STR_PT[hrc_title]="   🔎 Verificação de Reputação de Arquivo via Feeds de Ameaças em Tempo Real (VirusTotal + MalwareBazaar)"
STR_PT[hrc_disclaimer]="   Nota: esta é uma consulta de reputação de hash em feeds externos ao vivo — ela complementa as verificações heurísticas deste conjunto de ferramentas, não as substitui. Um resultado limpo aqui não garante que o arquivo seja 100% seguro (zero-day ainda é possível)."
