STR_PT[hrc_note]="   Lembrete: nenhuma ferramenta de detecção de ameaças atinge 100% de precisão — nem mesmo as grandes ferramentas comerciais. Combinar múltiplas fontes com monitoramento comportamental contínuo é o caminho prático mais próximo para reduzir riscos."
STR_PT[mw9_title]="   🧬 Varredura por Regras YARA-lite (detecção de ofuscação de conteúdo)"
STR_PT[mw9_disclaimer]="   Busca padrões no próprio conteúdo do arquivo (concatenação de strings, construção com chr(), escapes hexadecimais, poliglotas de imagem com PHP...) e não apenas uma assinatura literal — captura variantes ofuscadas de webshells conhecidas. Sempre revise um resultado manualmente antes de tomar uma ação."
STR_PT[mw9_pcre_unsupported]="   Nota: grep -P (PCRE) não é suportado neste sistema (comum no macOS/BSD ou em um grep Alpine mínimo) — a camada de regras YARA-lite é ignorada nesta execução, e a decisão depende apenas do detector clássico. Para suporte completo, instale o GNU grep (ex: apk add grep no Alpine, ou brew install grep no macOS)."
STR_PT[mw9_prompt_target]="   Caminho do arquivo ou diretório a escanear:"
STR_PT[mw9_real_yara_active]="   Um binário yara real + arquivos de regras .yar foram encontrados em rules/ — ele rodará como uma camada extra."
STR_PT[mw9_real_yara_inactive]="   Nenhum binário yara instalado (ou nenhum arquivo .yar em rules/) — utilizando apenas o mecanismo interno de regras lite."
