STR_PT[mw10_last_updates_title]="   Atualizações registradas recentemente:"
STR_PT[mw10_report_title]="   Relatório de Atualização de Regras — %s"
STR_PT[limitations_menu_option]="   Limitações Conhecidas"
STR_PT[limitations_title]="   ⚠️  Limitações Conhecidas da Ferramenta"
STR_PT[limitations_item1]="   Ainda não há detecção real baseada em comportamento — toda a ferramenta atualmente faz apenas análise estática (verificações de conteúdo/hash/entropia/YARA-lite). O monitoramento de processos em tempo de execução (conexões de rede em tempo real, comportamento suspeito durante a execução) ainda não foi desenvolvido."
STR_PT[limitations_item2]="   Fontes de regras ativas (rules_updater.sh + sources.txt) não foram verificadas contra uma fonte real — o mecanismo (validação de formato, backup, mesclagem) está construído e testado com fontes simuladas, mas desabilitado por padrão (enabled=0) porque nenhuma URL de fonte real foi verificada."
STR_PT[limitations_item3]="   O próprio raqib.sh não foi testado de ponta a ponta em uma máquina real — todos os testes atuais usam funções simuladas (stubs) no ambiente de desenvolvimento, não uma execução real completa do script."
STR_PT[limitations_item4]="   O caso do static_dropper no corpus de teste é uma lacuna deliberadamente mantida — um binário estático sem strings/comportamento visíveis sob análise estática, portanto, atualmente passa não detectado; este é um limite esperado de qualquer ferramenta apenas estática e precisa de uma camada comportamental ativa para ser corrigido."
STR_PT[limitations_item5]="   Zero regras .yar reais acompanham o projeto no momento — o suporte técnico para carregar e usar arquivos .yar com um binário yara real existe e está pronto, mas não há arquivos de regras reais a menos que uma fonte externa os forneça."
STR_PT[limitations_item6]="   Não foi testado em nenhum sistema operacional além do ambiente de desenvolvimento atual — nenhum teste no macOS ou em outras distribuições Linux até o momento."
STR_PT[update_menu_option]="   Verificar Atualizações"
