STR_HI[mw9_title]="   🧬 YARA-लाइट नियम स्कैन (सामग्री अस्पष्टता का पता लगाना)"
STR_HI[mw9_disclaimer]="   फ़ाइल की अपनी सामग्री में पैटर्न से मेल खाता है (स्ट्रिंग संयोजन, chr() निर्माण, hex escapes, PHP वाले छवि-पॉलीग्लॉट...) न केवल एक शाब्दिक हस्ताक्षर — ज्ञात वेबशेल के अस्पष्ट रूपों को पकड़ता है। कार्रवाई करने से पहले हमेशा मैन्युअल रूप से परिणाम की समीक्षा करें।"
STR_HI[mw9_pcre_unsupported]="   नोट: इस सिस्टम पर grep -P (PCRE) समर्थित नहीं है (macOS/BSD या न्यूनतम Alpine grep पर आम) — YARA-लाइट नियम परत इस बार छोड़ दी गई है, और निर्णय केवल क्लासिक डिटेक्टर पर निर्भर करता है। पूर्ण समर्थन के लिए, GNU grep स्थापित करें (उदा. Alpine पर apk add grep, या macOS पर brew install grep)।"
STR_HI[mw9_prompt_target]="   स्कैन करने के लिए फ़ाइल या निर्देशिका पथ:"
STR_HI[mw9_real_yara_active]="   rules/ के अंतर्गत एक वास्तविक yara बाइनरी + .yar नियम फ़ाइलें पाई गईं — यह एक अतिरिक्त परत के रूप में चलेगा।"
STR_HI[mw9_real_yara_inactive]="   कोई yara बाइनरी स्थापित नहीं है (या rules/ के तहत कोई .yar फ़ाइलें नहीं हैं) — केवल अंतर्निहित लाइट नियम इंजन पर वापस आ रहा है।"
STR_HI[mw9_score_line]="   स्कोर: %s | मिलान किए गए नियम: %s"
STR_HI[mw9_no_rules]="   कोई नहीं (केवल वास्तविक yara के माध्यम से मिलान किया गया)"
STR_HI[mw9_real_yara_hit]="   ⚠ वास्तविक yara नियमों से भी मेल खाया"
STR_HI[mw9_summary_line]="   स्कैन की गई %s फ़ाइल (फ़ाइलें) — %s संदिग्ध परिणाम।"
STR_HI[mw9_report_title]="   YARA-लाइट स्कैन रिपोर्ट — %s"
STR_HI[mw10_title]="   🔄 लाइव नियम अद्यतन"
STR_HI[mw10_disclaimer]="   tools/malware/rules/sources.txt में सक्षम स्रोतों से अद्यतन पहचान नियमों को खींचता है, किसी भी प्रतिस्थापन से पहले बैकअप लेता है, और आपके अपने स्थानीय नियमों को सुरक्षित रखता है। कोई आधिकारिक RAQIB सर्वर नहीं है — आप अपने खुद के स्रोतों को कॉन्फ़िगर और सत्यापित करते हैं।"
STR_HI[mw10_no_sources_file]="   rules/sources.txt नहीं मिला। अपेक्षित प्रारूप के लिए README देखें।"
STR_HI[mw10_fetching]="   प्राप्त किया जा रहा है [%s]: %s"
STR_HI[mw10_fetch_failed]="   स्रोत तक नहीं पहुंच सका (URL/अपने कनेक्शन की जांच करें)।"
STR_HI[mw10_fetch_empty]="   डाउनलोड की गई फ़ाइल खाली थी — छोड़ दिया गया।"
STR_HI[mw10_validating]="   नियम वाक्यविन्यास को सत्यापित किया जा रहा है..."
STR_HI[mw10_bad_line]="   पंक्ति %s (%s): अमान्य प्रारूप (अपेक्षित name|weight|regex)।"
STR_HI[mw10_bad_regex]="   पंक्ति %s (%s): अमान्य regex।"
STR_HI[mw10_validation_failed]="   सत्यापन विफल रहा — फ़ाइल अस्वीकृत, वर्तमान नियम अपरिवर्तित रखे गए।"
STR_HI[mw10_lite_updated]="   अद्यतन किया गया (पिछला नियम: %s, अब: %s — इसमें कोई भी संरक्षित स्थानीय नियम शामिल हैं)।"
STR_HI[mw10_not_yara_file]="   डाउनलोड की गई फ़ाइल एक वैध .yar फ़ाइल की तरह नहीं दिखती है (कोई 'rule' कीवर्ड नहीं मिला) — छोड़ दिया गया।"
STR_HI[mw10_yara_updated]="   वास्तविक YARA नियम इसमें सहेजे गए: %s"
STR_HI[mw10_yara_binary_missing]="   नोट: कोई yara बाइनरी स्थापित नहीं है — एक बार स्थापित होने के बाद इन नियमों का स्वतः उपयोग किया जाएगा।"
STR_HI[mw10_unknown_type]="   अज्ञात स्रोत प्रकार: %s (अपेक्षित लाइट या yara) — छोड़ दिया गया।"
STR_HI[mw10_done]="   अपडेट समाप्त हुआ।"
STR_HI[mw10_nothing_enabled]="   sources.txt में कोई भी स्रोत सक्षम (enabled=1) नहीं है — पहले फ़ाइल को संपादित करें और जिस स्रोत पर आप भरोसा करते हैं उसे सक्षम करें।"
STR_HI[mw10_last_updates_title]="   हाल ही में लॉग किए गए अपडेट:"
STR_HI[mw10_report_title]="   नियम अद्यतन रिपोर्ट — %s"
STR_HI[limitations_menu_option]="   ज्ञात सीमाएं"
STR_HI[limitations_title]="   ⚠️  टूल की ज्ञात सीमाएं"
STR_HI[limitations_item1]="   अभी तक कोई वास्तविक व्यवहार-आधारित पहचान नहीं है — पूरा टूल वर्तमान में केवल स्थैतिक विश्लेषण (सामग्री/हैश/एंट्रॉपी/YARA-लाइट जांच) है। लाइव रनटाइम प्रक्रिया निगरानी (वास्तविक समय नेटवर्क कनेक्शन, निष्पादन के दौरान संदिग्ध व्यवहार) अभी तक निर्मित नहीं है।"
STR_HI[limitations_item2]="   लाइव नियम स्रोत (rules_updater.sh + sources.txt) एक वास्तविक स्रोत के विरुद्ध असत्यापित हैं — तंत्र (प्रारूप सत्यापन, बैकअप, मर्ज) निर्मित और नकली स्रोतों के साथ परीक्षण किया गया है, लेकिन डिफ़ॉल्ट रूप से अक्षम (enabled=0) है क्योंकि कोई वास्तविक लाइव स्रोत URL सत्यापित नहीं किया गया है।"
STR_HI[limitations_item3]="   raqib.sh का स्वयं किसी वास्तविक मशीन पर एंड-टू-एंड परीक्षण नहीं किया गया है — सभी वर्तमान परीक्षण देव वातावरण के अंदर स्टब फ़ंक्शन का उपयोग करते हैं, स्क्रिप्ट का पूर्ण वास्तविक संचालन नहीं।"
STR_HI[limitations_item4]="   परीक्षण कोरपस में static_dropper मामला एक जानबूझकर छोड़ी गई कमी है — स्थैतिक विश्लेषण के तहत कोई दृश्यमान स्ट्रिंग्स/व्यवहार के बिना एक स्थैतिक बाइनरी, इसलिए यह वर्तमान में बिना पहचाने चला जाता है; यह किसी भी केवल-स्थैतिक उपकरण की एक अपेक्षित सीमा है और इसे बंद करने के लिए एक लाइव व्यावहारिक परत की आवश्यकता होती है।"
STR_HI[limitations_item5]="   परियोजना के साथ अभी शून्य वास्तविक .yar नियम आते हैं — एक वास्तविक yara बाइनरी के साथ .yar फ़ाइलों को लोड करने और उपयोग करने के लिए तकनीकी सहायता मौजूद है और तैयार है, लेकिन जब तक कोई बाहरी स्रोत प्रदान नहीं करता तब तक कोई वास्तविक नियम फ़ाइलें नहीं हैं।"
STR_HI[limitations_item6]="   वर्तमान विकास वातावरण के अलावा किसी भी OS पर परीक्षण नहीं किया गया है — macOS पर या अन्य Linux वितरणों पर अभी तक कोई परीक्षण नहीं हुआ है।"
STR_HI[update_menu_option]="   अपडेट के लिए जांचें"
STR_HI[upd_title]="   === RAQIB अपडेट के लिए जांचें ==="
STR_HI[upd_current_version]="   वर्तमान में स्थापित संस्करण: %s"
STR_HI[upd_checking]="   एक नए संस्करण की जांच की जा रही है..."
STR_HI[upd_disabled]="   अपडेट जांचना सक्षम नहीं है। प्रोजेक्ट रूट पर update_source.txt को संपादित करें, इसे आपके द्वारा नियंत्रित URL (जैसे आपका अपना रिपॉजिटरी) पर इंगित करें, और इसे पहले सक्षम (enabled=1) करें।"
STR_HI[upd_fetch_failed]="   संस्करण की जानकारी प्राप्त नहीं की जा सकी। अपने कनेक्शन या update_source.txt में URL की जांच करें।"
STR_HI[upd_available]="   🎉 एक नया संस्करण उपलब्ध है: v%s — इसे मैन्युअल रूप से डाउनलोड करने के लिए नीचे दिए गए लिंक (या अपने रिपॉजिटरी) की जांच करें।"
STR_HI[upd_up_to_date]="   आप पहले से ही नवीनतम संस्करण पर हैं। कोई अपडेट उपलब्ध नहीं है।"

