STR_IT[hrc_note]="   Promemoria: nessuno strumento di rilevamento minacce raggiunge il 100% di accuratezza — nemmeno i grandi strumenti commerciali. Combinare più fonti con un monitoraggio comportamentale continuo è la via pratica più vicina per ridurre i rischi."
STR_IT[mw9_title]="   🧬 Scansione Regole YARA-lite (rilevamento offuscamento contenuti)"
STR_IT[mw9_disclaimer]="   Trova corrispondenze di modelli nel contenuto stesso del file (concatenazione di stringhe, costruzione di chr(), escape esadecimali, poliglotta immagine con PHP...) non solo una firma letterale — cattura varianti offuscate di web shell note. Esamina sempre manualmente un risultato prima di agire."
STR_IT[mw9_pcre_unsupported]="   Nota: grep -P (PCRE) non è supportato su questo sistema (comune su macOS/BSD o un grep Alpine minimo) — il livello delle regole YARA-lite viene ignorato in questa esecuzione e la decisione si basa solo sul rilevatore classico. Per un supporto completo, installa GNU grep (es. apk add grep su Alpine, o brew install grep su macOS)."
STR_IT[mw9_prompt_target]="   Percorso del file o della directory da scansionare:"
