STR_IT[mw10_last_updates_title]="   Aggiornamenti registrati di recente:"
STR_IT[mw10_report_title]="   Report Aggiornamento Regole — %s"
STR_IT[limitations_menu_option]="   Limitazioni Note"
STR_IT[limitations_title]="   ⚠️  Limitazioni Note dello Strumento"
STR_IT[limitations_item1]="   Nessun rilevamento reale basato sul comportamento al momento — l'intero strumento attualmente esegue solo analisi statica (controlli contenuto/hash/entropia/YARA-lite). Il monitoraggio dei processi in tempo reale (connessioni di rete in tempo reale, comportamento sospetto durante l'esecuzione) non è ancora integrato."
STR_IT[limitations_item2]="   Le fonti delle regole in tempo reale (rules_updater.sh + sources.txt) non sono verificate rispetto a una fonte reale — il meccanismo (validazione del formato, backup, unione) è costruito e testato con fonti simulate, ma disabilitato per impostazione predefinita (enabled=0) perché nessun URL di fonte reale è stato verificato."
STR_IT[limitations_item3]="   raqib.sh stesso non è stato testato end-to-end su una macchina reale — tutti i test attuali utilizzano funzioni stub all'interno dell'ambiente di sviluppo, non un'esecuzione reale completa dello script."
STR_IT[limitations_item4]="   Il caso static_dropper nel corpus di test è una lacuna deliberatamente lasciata — un binario statico senza stringhe/comportamento visibili sotto analisi statica, quindi attualmente non viene rilevato; questo è un limite previsto di qualsiasi strumento solo statico e richiede un livello comportamentale in tempo reale per essere colmato."
STR_IT[limitations_item5]="   Zero regole .yar reali sono fornite con il progetto in questo momento — il supporto tecnico per caricare e utilizzare file .yar con un vero binario yara esiste ed è pronto, ma non ci sono file di regole effettivi a meno che una fonte esterna non ne fornisca uno."
STR_IT[limitations_item6]="   Non testato su nessun sistema operativo diverso dall'attuale ambiente di sviluppo — nessun test su macOS o su altre distribuzioni Linux finora."
STR_IT[update_menu_option]="   Verifica Aggiornamenti"
