STR_FR[hrc_disclaimer]="Remarque : ceci est une recherche de réputation par hash sur des flux externes en direct — cela complète les vérifications heuristiques de cette boîte à outils, sans les remplacer. Un résultat propre ici ne garantit pas que le fichier est sûr à 100 % (un zero-day reste possible)."
STR_FR[hrc_no_curl]="Cet outil nécessite curl, introuvable sur ce système. Installez-le et réessayez."
STR_FR[hrc_report_header]="Rapport de réputation de hash"
STR_FR[hrc_checking_mb]="Vérification auprès de MalwareBazaar (abuse.ch)"
