STR_FR[hrc_vt_no_key_prompt]="La recherche VirusTotal nécessite une clé API gratuite (créez un compte gratuit sur virustotal.com et copiez-la depuis les paramètres de votre profil). Laissez vide pour ignorer cette vérification."
STR_FR[hrc_vt_key_prompt]="Clé API VirusTotal (facultatif) : "
