STR_FR[hrc_checking_vt]="Vérification auprès de VirusTotal"
STR_FR[hrc_vt_result_label]="Résultat VirusTotal"
STR_FR[hrc_vt_hit]="⚠ %s moteurs le signalent comme malveillant, %s comme suspect (sur %s moteurs)"
STR_FR[hrc_vt_clean]="Aucune détection malveillante parmi %s moteurs d'analyse"
STR_FR[hrc_vt_unknown]="Fichier inconnu de VirusTotal (jamais soumis auparavant — ne signifie pas qu'il est sûr)"
STR_FR[hrc_vt_bad_key]="Clé API VirusTotal invalide. La copie enregistrée a été supprimée — entrez une clé valide la prochaine fois."
STR_FR[hrc_vt_error]="Impossible de joindre VirusTotal (code de réponse : %s)"
STR_FR[hrc_note]="Rappel : aucun outil de détection de menaces n'atteint 100 % de précision — même les grands outils commerciaux. Combiner plusieurs sources avec une surveillance comportementale continue est la voie pratique la plus proche pour réduire les risques."
STR_FR[mw9_title]="🧬 Analyse par règles YARA-lite (détection d'obfuscation de contenu)"
STR_FR[mw9_disclaimer]="Recherche des motifs dans le contenu même du fichier (concaténation de chaînes, construction via chr(), échappements hexadécimaux, polyglottes image-PHP...) et pas seulement une signature littérale — capture les variantes obfusquées de webshells connus. Vérifiez toujours un résultat manuellement avant d'agir."
STR_FR[mw9_pcre_unsupported]="Remarque : grep -P (PCRE) n'est pas pris en charge sur ce système (courant sur macOS/BSD ou un grep Alpine minimal) — la couche de règles YARA-lite est ignorée cette fois, et la décision repose uniquement sur le détecteur classique. Pour un support complet, installez GNU grep (ex. apk add grep sur Alpine, ou brew install grep sur macOS)."
STR_FR[mw9_prompt_target]="Chemin du fichier ou du répertoire à analyser : "
STR_FR[mw9_real_yara_active]="Un binaire yara réel + des fichiers de règles .yar ont été trouvés sous rules/ — il s'exécutera comme une couche supplémentaire."
STR_FR[mw9_real_yara_inactive]="Aucun binaire yara installé (ou aucun fichier .yar sous rules/) — repli sur le moteur de règles lite intégré uniquement."
STR_FR[mw9_score_line]="Score : %s | Règles correspondantes : %s"
STR_FR[mw9_no_rules]="aucune (correspondance via yara réel uniquement)"
STR_FR[mw9_real_yara_hit]="⚠ A également correspondu à de vraies règles yara"
STR_FR[mw9_summary_line]="%s fichier(s) analysé(s) — %s résultat(s) suspect(s)."
STR_FR[mw9_report_title]="Rapport d'analyse YARA-lite — %s"
STR_FR[mw10_title]="🔄 Mise à jour des règles en direct"
STR_FR[mw10_disclaimer]="Récupère des règles de détection mises à jour depuis les sources activées dans tools/malware/rules/sources.txt, effectue une sauvegarde avant tout remplacement, et préserve vos propres règles locales. Il n'existe aucun serveur RAQIB officiel — vous configurez et vérifiez vos propres sources."
STR_FR[mw10_no_sources_file]="rules/sources.txt introuvable. Consultez le README pour le format attendu."
