STR_ES[hrc_note]="Recordatorio: ninguna herramienta de detección de amenazas alcanza el 100% de precisión — ni siquiera las grandes herramientas comerciales. Combinar múltiples fuentes con monitoreo conductual continuo es la vía práctica más cercana para reducir riesgos."
STR_ES[mw9_title]="🧬 Escaneo de reglas YARA-lite (detección de ofuscación de contenido)"
