STR_DE[hrc_disclaimer]="Hinweis: Dies ist eine Hash-Reputationsabfrage gegen externe Live-Feeds — sie ergänzt die heuristischen Prüfungen dieses Toolkits, ersetzt sie aber nicht. Ein sauberes Ergebnis hier garantiert nicht, dass die Datei zu 100 % sicher ist (ein Zero-Day ist weiterhin möglich)."
STR_DE[hrc_no_curl]="Dieses Tool benötigt curl, das auf diesem System nicht gefunden wurde. Installieren Sie es und versuchen Sie es erneut."
STR_DE[hrc_report_header]="Hash-Reputationsbericht"
STR_DE[hrc_checking_mb]="Prüfung bei MalwareBazaar (abuse.ch)"
STR_DE[hrc_mb_result_label]="MalwareBazaar-Ergebnis"
STR_DE[hrc_mb_hit]="⚠ Übereinstimmung gefunden! Klassifiziert als: %s — Dateityp: %s"
STR_DE[hrc_mb_clean]="Nicht in MalwareBazaar gefunden (bedeutet nicht zwangsläufig, dass es sicher ist)"
STR_DE[hrc_mb_error]="MalwareBazaar konnte nicht erreicht werden (Internetverbindung prüfen)"
STR_DE[hrc_vt_no_key_prompt]="Die VirusTotal-Abfrage benötigt einen kostenlosen API-Schlüssel (erstellen Sie ein kostenloses Konto auf virustotal.com und kopieren Sie ihn aus Ihren Profileinstellungen). Leer lassen, um diese Prüfung zu überspringen."
STR_DE[hrc_vt_key_prompt]="VirusTotal-API-Schlüssel (optional): "
STR_DE[hrc_vt_save_prompt]="Schlüssel lokal speichern, damit er nächstes Mal nicht erneut eingegeben werden muss? (j/n): "
STR_DE[hrc_vt_skipped]="VirusTotal-Prüfung übersprungen (kein API-Schlüssel angegeben)"
STR_DE[hrc_checking_vt]="Prüfung bei VirusTotal"
STR_DE[hrc_vt_result_label]="VirusTotal-Ergebnis"
STR_DE[hrc_vt_hit]="⚠ %s Engines stufen es als bösartig ein, %s als verdächtig (von %s Engines)"
STR_DE[hrc_vt_clean]="Keine bösartige Erkennung bei %s Scan-Engines"
STR_DE[hrc_vt_unknown]="Datei bei VirusTotal unbekannt (noch nie eingereicht — bedeutet nicht, dass sie sicher ist)"
STR_DE[hrc_vt_bad_key]="Ungültiger VirusTotal-API-Schlüssel. Die gespeicherte Kopie wurde entfernt — geben Sie beim nächsten Mal einen gültigen Schlüssel ein."
STR_DE[hrc_vt_error]="VirusTotal konnte nicht erreicht werden (Antwortcode: %s)"
STR_DE[hrc_note]="Erinnerung: Kein Tool zur Bedrohungserkennung erreicht 100 % Genauigkeit — nicht einmal große kommerzielle Tools. Die Kombination mehrerer Quellen mit fortlaufender Verhaltensüberwachung ist der praktikabelste Weg, um Risiken zu reduzieren."
STR_DE[mw9_title]="🧬 YARA-lite-Regel-Scan (Erkennung von Inhaltsverschleierung)"
STR_DE[mw9_disclaimer]="Sucht nach Mustern im Dateiinhalt selbst (String-Verkettung, chr()-Konstruktion, Hex-Escapes, PHP-Bild-Polyglotte...) nicht nur nach einer wörtlichen Signatur — erfasst verschleierte Varianten bekannter Webshells. Überprüfen Sie ein Ergebnis vor dem Handeln immer manuell."
STR_DE[mw9_pcre_unsupported]="Hinweis: grep -P (PCRE) wird auf diesem System nicht unterstützt (üblich bei macOS/BSD oder einem minimalen Alpine-grep) — die YARA-lite-Regelschicht wird diesmal übersprungen, und die Entscheidung beruht nur auf dem klassischen Detektor. Für vollständige Unterstützung installieren Sie GNU grep (z. B. apk add grep unter Alpine oder brew install grep unter macOS)."
STR_DE[mw9_prompt_target]="Pfad zur zu scannenden Datei oder zum Verzeichnis: "
STR_DE[mw9_real_yara_active]="Ein echtes yara-Binary + .yar-Regeldateien wurden unter rules/ gefunden — es wird als zusätzliche Schicht ausgeführt."
STR_DE[mw9_real_yara_inactive]="Kein yara-Binary installiert (oder keine .yar-Dateien unter rules/) — Rückgriff nur auf die eingebaute Lite-Regel-Engine."
STR_DE[mw9_score_line]="Punktzahl: %s | Übereinstimmende Regeln: %s"
STR_DE[mw9_no_rules]="keine (nur über echtes yara übereinstimmend)"
STR_DE[mw9_real_yara_hit]="⚠ Stimmte auch mit echten yara-Regeln überein"
STR_DE[mw9_summary_line]="%s Datei(en) gescannt — %s verdächtige(s) Ergebnis(se)."
STR_DE[mw9_report_title]="YARA-lite-Scan-Bericht — %s"
STR_DE[mw10_title]="🔄 Live-Regel-Update"
STR_DE[mw10_disclaimer]="Ruft aktualisierte Erkennungsregeln von den in tools/malware/rules/sources.txt aktivierten Quellen ab, erstellt vor jedem Ersetzen ein Backup und bewahrt Ihre eigenen lokalen Regeln. Es gibt keinen offiziellen RAQIB-Server — Sie konfigurieren und verifizieren Ihre eigenen Quellen."
STR_DE[mw10_no_sources_file]="rules/sources.txt nicht gefunden. Siehe README für das erwartete Format."
STR_DE[mw10_fetching]="Abrufen von [%s]: %s"
