STR_DE[mw10_not_yara_file]="Die heruntergeladene Datei scheint keine gültige .yar-Datei zu sein (kein 'rule'-Schlüsselwort gefunden) — übersprungen."
STR_DE[mw10_yara_updated]="Echte YARA-Regeln gespeichert unter: %s"
STR_DE[mw10_yara_binary_missing]="Hinweis: kein yara-Binary installiert — diese Regeln werden automatisch verwendet, sobald es installiert ist."
STR_DE[mw10_unknown_type]="Unbekannter Quelltyp: %s (erwartet lite oder yara) — übersprungen."
