STR_ID[mw9_disclaimer]="Mencocokkan pola dalam konten file itu sendiri (penggabungan string, konstruksi chr(), escape hex, poliglot gambar-dengan-PHP...) tidak hanya tanda tangan literal — menangkap varian tersamar dari webshell yang diketahui. Selalu tinjau hasil secara manual sebelum bertindak."
STR_ID[mw9_pcre_unsupported]="Catatan: grep -P (PCRE) tidak didukung di sistem ini (umum di macOS/BSD atau grep Alpine minimal) — lapisan aturan YARA-lite dilewati kali ini, dan keputusan hanya mengandalkan detektor klasik. Untuk dukungan penuh, pasang GNU grep (mis. apk add grep di Alpine, atau brew install grep di macOS)."
