STR_ID[limitations_menu_option]="Batasan yang Diketahui"
STR_ID[limitations_title]="⚠️  Batasan Alat yang Diketahui"
STR_ID[limitations_item1]="Belum ada deteksi berbasis perilaku nyata — seluruh alat saat ini hanya melakukan analisis statis (pemeriksaan konten/hash/entropi/YARA-lite). Pemantauan proses runtime langsung (koneksi jaringan real-time, perilaku mencurigakan selama eksekusi) belum dibangun."
STR_ID[limitations_item2]="Sumber aturan langsung (rules_updater.sh + sources.txt) belum diverifikasi terhadap sumber nyata — mekanismenya (validasi format, cadangan, penggabungan) sudah dibangun dan diuji dengan sumber tiruan, tetapi dinonaktifkan secara default (enabled=0) karena belum ada URL sumber langsung nyata yang diverifikasi."
STR_ID[limitations_item3]="raqib.sh sendiri belum diuji end-to-end pada mesin nyata — semua pengujian saat ini menggunakan fungsi stub di dalam lingkungan pengembangan, bukan eksekusi nyata penuh dari skrip."
STR_ID[limitations_item4]="Kasus static_dropper dalam korpus uji adalah celah yang diketahui dan sengaja dibiarkan — biner statis tanpa string/perilaku yang terlihat di bawah analisis statis, sehingga saat ini tidak terdeteksi; ini adalah batasan yang diharapkan dari alat statis-saja dan memerlukan lapisan perilaku langsung untuk menutupnya."
STR_ID[limitations_item5]="Nol aturan .yar nyata disertakan dengan proyek saat ini — dukungan teknis untuk memuat dan menggunakan file .yar dengan binari yara asli ada dan siap, tetapi tidak ada file aturan aktual kecuali sumber eksternal menyediakannya."
STR_ID[limitations_item6]="Belum diuji pada OS mana pun selain lingkungan pengembangan saat ini — belum ada pengujian di macOS atau distribusi Linux lainnya."
