STR_JA[limitations_menu_option]="既知の制限事項"
STR_JA[limitations_title]="⚠️  ツールの既知の制限事項"
STR_JA[limitations_item1]="実際の行動ベースの検知はまだありません — ツール全体は現在、静的分析のみです（コンテンツ/ハッシュ/エントロピー/YARA-liteチェック）。ライブランタイムプロセス監視（リアルタイムのネットワーク接続、実行中の疑わしい行動）はまだ構築されていません。"
STR_JA[limitations_item2]="ライブルールソース（rules_updater.sh + sources.txt）は実際のソースに対して検証されていません — メカニズム（形式検証、バックアップ、マージ）は構築され、模擬ソースでテストされていますが、実際のライブソースURLが検証されていないため、デフォルトでは無効です（enabled=0）。"
STR_JA[limitations_item3]="raqib.sh自体は実機でエンドツーエンドのテストが行われていません — 現在のすべてのテストは開発環境内でスタブ関数を使用しており、スクリプトの完全な実際の実行ではありません。"
STR_JA[limitations_item4]="テストコーパスのstatic_dropperケースは既知の意図的に残されたギャップです — 静的分析の下で目に見える文字列/動作がない静的バイナリであるため、現在は検出されません。これは静的専用ツールに予想される制限であり、閉じるにはライブの行動レイヤーが必要です。"
STR_JA[limitations_item5]="現在、プロジェクトには実際の.yarルールが1つも同梱されていません — 実際のyaraバイナリで.yarファイルを読み込んで使用する技術サポートは存在し準備ができていますが、外部ソースが提供しない限り実際のルールファイルはありません。"
STR_JA[limitations_item6]="現在の開発環境以外のOSではテストされていません — macOSや他のLinuxディストリビューションでのテストはまだ行われていません。"
