STR_NL[hrc_title]="🔎 Bestandsreputatiecontrole via Live Dreigingsfeeds (VirusTotal + MalwareBazaar)"
STR_NL[hrc_disclaimer]="Opmerking: dit is een hash-reputatiezoekopdracht tegen live externe feeds — het vult de heuristische controles van deze toolkit aan, maar vervangt ze niet. Een schoon resultaat hier garandeert niet dat het bestand 100% veilig is (een zero-day blijft mogelijk)."
STR_NL[hrc_no_curl]="Deze tool vereist curl, dat niet is gevonden op dit systeem. Installeer het en probeer het opnieuw."
STR_NL[hrc_report_header]="Hash-reputatierapport"
STR_NL[hrc_checking_mb]="Controleren bij MalwareBazaar (abuse.ch)"
