STR_NL[hrc_vt_no_key_prompt]="Voor de VirusTotal-zoekopdracht is een gratis API-sleutel nodig (maak een gratis account aan op virustotal.com en kopieer deze uit uw profielinstellingen). Laat leeg om deze controle over te slaan."
