STR_NL[hrc_vt_result_label]="VirusTotal-resultaat"
STR_NL[hrc_vt_hit]="⚠ %s engines markeren het als kwaadaardig, %s als verdacht (van %s engines)"
STR_NL[hrc_vt_clean]="Geen kwaadaardige detectie bij %s scan-engines"
STR_NL[hrc_vt_unknown]="Bestand onbekend bij VirusTotal (nog nooit eerder ingediend — betekent niet dat het veilig is)"
