STR_NL[hrc_vt_error]="Kan VirusTotal niet bereiken (responscode: %s)"
STR_NL[hrc_note]="Herinnering: geen enkele dreigingsdetectietool bereikt 100% nauwkeurigheid — zelfs grote commerciële tools niet. Het combineren van meerdere bronnen met continue gedragsmonitoring is de meest praktische manier om risico's te verminderen."
STR_NL[mw9_title]="🧬 YARA-lite Regelscan (detectie van inhoudsverduistering)"
STR_NL[mw9_disclaimer]="Zoekt naar patronen in de inhoud van het bestand zelf (stringconcatenatie, chr()-constructie, hex-escapes, afbeelding-polyglots met PHP...), niet alleen een letterlijke signatuur — vangt versluierde varianten van bekende webshells op. Controleer een resultaat altijd handmatig voordat u actie onderneemt."
STR_NL[mw9_pcre_unsupported]="Opmerking: grep -P (PCRE) wordt niet ondersteund op dit systeem (gebruikelijk op macOS/BSD of een minimale Alpine grep) — de YARA-lite regellaag wordt deze keer overgeslagen, en de beslissing is alleen gebaseerd op de klassieke detector. Installeer voor volledige ondersteuning GNU grep (bijv. apk add grep op Alpine, of brew install grep op macOS)."
STR_NL[mw9_prompt_target]="Pad naar het te scannen bestand of directory: "
STR_NL[mw9_real_yara_active]="Een echte yara-binary + .yar-regelbestanden gevonden onder rules/ — zal als extra laag draaien."
STR_NL[mw9_real_yara_inactive]="Geen yara-binary geïnstalleerd (of geen .yar-bestanden onder rules/) — terugvallen op alleen de ingebouwde lite-regelengine."
