STR_NL[mw10_title]="🔄 Live Regelupdate"
STR_NL[mw10_disclaimer]="Haalt bijgewerkte detectieregels op van de bronnen die zijn ingeschakeld in tools/malware/rules/sources.txt, maakt een back-up voor elke vervanging en behoudt uw eigen lokale regels. Er is geen officiële RAQIB-server — u configureert en verifieert uw eigen bronnen."
