STR_NL[mw10_nothing_enabled]="Geen enkele bron is ingeschakeld (enabled=1) in sources.txt — bewerk het bestand en schakel eerst een vertrouwde bron in."
STR_NL[mw10_last_updates_title]="Recent geregistreerde updates:"
STR_NL[mw10_report_title]="Regelupdate-rapport — %s"
STR_NL[limitations_menu_option]="Bekende Beperkingen"
STR_NL[limitations_title]="⚠️  Bekende Beperkingen van de Tool"
STR_NL[limitations_item1]="Nog geen echte gedragsgebaseerde detectie — de hele tool voert momenteel alleen statische analyse uit (inhouds-/hash-/entropie-/YARA-lite controles). Live runtime procesmonitoring (realtime netwerkverbindingen, verdacht gedrag tijdens uitvoering) is nog niet gebouwd."
STR_NL[limitations_item2]="Live regelbronnen (rules_updater.sh + sources.txt) zijn niet geverifieerd tegen een echte bron — het mechanisme (formaatvalidatie, back-up, samenvoegen) is gebouwd en getest met nagebootste bronnen, maar standaard uitgeschakeld (enabled=0) omdat er geen echte live bron-URL is geverifieerd."
STR_NL[limitations_item3]="raqib.sh zelf is niet end-to-end getest op een echte machine — alle huidige tests gebruiken stub-functies binnen de ontwikkelomgeving, geen volledige echte uitvoering van het script."
STR_NL[limitations_item4]="Het static_dropper-geval in de testcorpus is een bekend, opzettelijk achtergelaten hiaat — een statische binary zonder zichtbare strings/gedrag onder statische analyse, waardoor het momenteel onopgemerkt blijft; dit is een verwachte beperking van elke uitsluitend statische tool en vereist een live gedragslaag om te sluiten."
STR_NL[limitations_item5]="Er zijn momenteel nul echte .yar-regels bij het project inbegrepen — technische ondersteuning voor het laden en gebruiken van .yar-bestanden met een echte yara-binary bestaat en is gereed, maar er zijn geen daadwerkelijke regelbestanden tenzij een externe bron er een levert."
STR_NL[limitations_item6]="Niet getest op enig ander besturingssysteem dan de huidige ontwikkelomgeving — nog geen tests op macOS of andere Linux-distributies."
STR_NL[update_menu_option]="Updates Controleren"
STR_NL[upd_title]="=== RAQIB-updates Controleren ==="
