STR_NL[upd_fetch_failed]="Kan versie-informatie niet ophalen. Controleer uw verbinding of de URL in update_source.txt."
STR_NL[upd_available]="🎉 Er is een nieuwe versie beschikbaar: v%s — controleer de onderstaande link (of uw repository) om deze handmatig te downloaden."
STR_NL[upd_up_to_date]="U gebruikt al de nieuwste versie. Geen updates beschikbaar."

