STR_KO[limitations_item4]="테스트 코퍼스의 static_dropper 케이스는 알려진 의도적으로 남겨진 간극입니다 — 정적 분석 하에서 보이는 문자열/행동이 없는 정적 바이너리이므로 현재는 탐지되지 않습니다. 이는 정적 전용 도구의 예상되는 한계이며 이를 해결하려면 라이브 행동 계층이 필요합니다."
