STR_UK[mw9_title]="🧬 Сканування правил YARA-lite (виявлення обфускації вмісту)"
STR_UK[mw9_disclaimer]="Шукає збіги шаблонів у самому вмісті файлу (конкатенація рядків, побудова через chr(), шістнадцяткові escape-послідовності, поліглоти зображень з PHP...), а не лише буквальний підпис — виявляє обфусковані варіанти відомих веб-шелів. Завжди перевіряйте результат вручну перед тим, як діяти."
STR_UK[mw9_pcre_unsupported]="Примітка: grep -P (PCRE) не підтримується в цій системі (поширено в macOS/BSD або мінімальному grep Alpine) — цього разу шар правил YARA-lite пропускається, і рішення покладається лише на класичний детектор. Для повної підтримки встановіть GNU grep (напр., apk add grep в Alpine, або brew install grep в macOS)."
