STR_UK[limitations_menu_option]="Відомі обмеження"
STR_UK[limitations_title]="⚠️  Відомі обмеження інструменту"
STR_UK[limitations_item1]="Ще немає реального виявлення на основі поведінки — весь інструмент наразі виконує лише статичний аналіз (перевірки вмісту/хешу/ентропії/YARA-lite). Моніторинг процесів у реальному часі (мережеві з'єднання в реальному часі, підозріла поведінка під час виконання) ще не реалізовано."
STR_UK[limitations_item2]="Джерела активних правил (rules_updater.sh + sources.txt) не перевірені на реальному джерелі — механізм (перевірка формату, резервне копіювання, об'єднання) побудований і протестований на симульованих джерелах, але вимкнений за замовчуванням (enabled=0), оскільки жодна реальна URL-адреса живого джерела не перевірена."
STR_UK[limitations_item3]="Сам raqib.sh не пройшов наскрізного тестування на реальній машині — усі поточні тести використовують заглушкові функції в середовищі розробки, а не повне реальне виконання скрипту."
STR_UK[limitations_item4]="Випадок static_dropper у тестовому корпусі — це відомий, навмисно залишений пробіл — статичний бінарний файл без видимих рядків/поведінки при статичному аналізі, тому наразі він проходить непоміченим; це очікуване обмеження будь-якого суто статичного інструменту, і для його усунення потрібен живий поведінковий шар."
STR_UK[limitations_item5]="Наразі до проекту не додано жодного справжнього правила .yar — технічна підтримка для завантаження та використання файлів .yar зі справжнім бінарним файлом yara існує та готова, але немає фактичних файлів правил, якщо зовнішнє джерело їх не надасть."
STR_UK[limitations_item6]="Не протестовано на жодній операційній системі, крім поточного середовища розробки — тестування на macOS чи інших дистрибутивах Linux ще не проводилося."
