STR_PL[mw9_disclaimer]="Wyszukuje wzorce w samej zawartości pliku (konkatenacja ciągów, konstrukcja chr(), sekwencje ucieczki hex, poligloty obrazów z PHP...) nie tylko dosłowną sygnaturę — wykrywa zaciemnione warianty znanych webshelli. Zawsze ręcznie przejrzyj wynik przed podjęciem działania."
STR_PL[mw9_pcre_unsupported]="Uwaga: grep -P (PCRE) nie jest obsługiwane w tym systemie (powszechne w macOS/BSD lub minimalnym grep Alpine) — warstwa reguł YARA-lite jest tym razem pomijana, a decyzja opiera się wyłącznie na klasycznym detektorze. Aby uzyskać pełne wsparcie, zainstaluj GNU grep (np. apk add grep w Alpine, lub brew install grep w macOS)."
