STR_PL[limitations_menu_option]="Znane Ograniczenia"
STR_PL[limitations_title]="⚠️  Znane Ograniczenia Narzędzia"
STR_PL[limitations_item1]="Jeszcze brak rzeczywistego wykrywania opartego na zachowaniu — całe narzędzie obecnie wykonuje tylko analizę statyczną (kontrole zawartości/skrótu/entropii/YARA-lite). Monitorowanie procesów w czasie rzeczywistym (rzeczywiste połączenia sieciowe, podejrzane zachowanie podczas wykonywania) nie zostało jeszcze zbudowane."
STR_PL[limitations_item2]="Źródła reguł na żywo (rules_updater.sh + sources.txt) nie zostały zweryfikowane względem rzeczywistego źródła — mechanizm (walidacja formatu, kopia zapasowa, scalanie) jest zbudowany i przetestowany na symulowanych źródłach, ale domyślnie wyłączony (enabled=0), ponieważ żaden rzeczywisty adres URL źródła na żywo nie został zweryfikowany."
STR_PL[limitations_item3]="Sam raqib.sh nie został przetestowany od początku do końca na rzeczywistej maszynie — wszystkie obecne testy wykorzystują funkcje zaślepek w środowisku deweloperskim, a nie pełne rzeczywiste wykonanie skryptu."
STR_PL[limitations_item4]="Przypadek static_dropper w korpusie testowym to znana, celowo pozostawiona luka — statyczny plik binarny bez widocznych ciągów/zachowania w analizie statycznej, więc obecnie pozostaje niewykryty; jest to oczekiwane ograniczenie każdego narzędzia wyłącznie statycznego i wymaga warstwy behawioralnej na żywo, aby to zamknąć."
STR_PL[limitations_item5]="Obecnie do projektu nie dołączono żadnych prawdziwych reguł .yar — techniczne wsparcie do ładowania i używania plików .yar z prawdziwym plikiem binarnym yara istnieje i jest gotowe, ale nie ma rzeczywistych plików reguł, chyba że dostarczy je zewnętrzne źródło."
STR_PL[limitations_item6]="Nie testowano na żadnym systemie operacyjnym innym niż obecne środowisko deweloperskie — jak dotąd brak testów na macOS lub innych dystrybucjach Linux."
